import * as M from './model.js';
import * as A from './academic-year.js';
import * as People from './community-life.js';
import * as Vote from './school-democracy.js';
import * as Network from './staff-network.js';
import * as Review from './school-review.js';
import * as W from './staff-work.js';
import * as Library from './library-life.js';

export function createCommunityUI(h){
 const {get,esc,q,val,num,btn,text,field,select,dates,open,outcome,ctx}=h;
 const studentSelect=(id,value)=>select(id,get().students.map(st=>[st.id,st.name]),value);
 const input=(id,placeholder='')=>`<input id="${id}" maxlength="100" placeholder="${esc(placeholder)}">`;
 const attrs=id=>`data-id="${esc(id)}"`;
 function coverCard(v){const s=get(),c=Network.data(s).covers.find(c=>c.volunteerId===v.id&&c.schoolId===(s.career?.schoolId||'default'));if(!c)return '';const names={requested:'학교 회신 대기',scheduled:'지원 담당 배정',reported:'활동 결과 도착',confirmed:'결과 확인 완료',unavailable:'배정 불가 · 일정 조정 필요',cancelled:'취소'};return `<div class="notice"><b>${names[c.status]}</b>${c.personId?`<div class="beta-row">${ctx.portrait(c.personId,'sm')}<span>${esc(M.NPCS.find(n=>n.id===c.personId)?.name)} · 학교 지원</span></div>`:''}${c.report?`<p>${esc(c.report)}</p>`:''}${c.status==='reported'?btn('담당자 결과 확인','beta-cover-ack',attrs(c.id)):''}<small>보호자의 취소 기록은 유지됩니다. 학생에게 불이익이 없습니다.</small></div>`;}
 const empty=body=>body||'<p class="empty">아직 기록이 없습니다.</p>';
 const records=rows=>empty(rows.map(x=>`<article class="beta-card"><small class="time-highlight">${esc(x.date||x.created)}</small><p>${esc(x.text||x.note||x.reason||x.result||x.detail||'')}</p>${x.response?`<blockquote>${esc(x.response)}</blockquote>`:''}</article>`).join(''));
 const navigation=()=>`<div class="buttons">${[['community','생활·관계'],['family','보호자·전입전출'],['belongings','물건·정리'],['election-full','전교 선거'],['governance','위원·봉사'],['evaluation','평가 실시'],['operations-detail','업무·시수']].map(([a,t])=>btn(t,'beta-'+a)).join('')}</div>`;
 function page(title,body){open(title,navigation()+body);}
 function community(){const s=get(),d=People.data(s);page('사람과 일상의 기록',`<p class="intro">학생끼리와 교직원끼리 나눈 일도 인물 관계에 남습니다. 다른 학년이 되어도 같은 인물의 기록을 이어갑니다.</p><div class="beta-grid">${Object.values(d.edges).sort((a,b)=>b.history.length-a.history.length).slice(0,18).map(e=>`<article class="beta-card"><b class="person-highlight">${esc(d.people[e.a]?.name)} · ${esc(d.people[e.b]?.name)}</b><p>관계 ${e.trust}/100 · ${esc(e.history[0]?.text)}</p></article>`).join('')}</div><h4>학교 안에서 오간 이야기</h4>${empty(d.socialFeed.slice(0,16).map(f=>`<article class="beta-card"><b>${esc(f.nameA)} · ${esc(f.nameB)}</b><small class="time-highlight">${esc(f.date)}</small><p>${esc(f.text)}</p><blockquote>${esc(f.line)}</blockquote></article>`).join(''))}<h4>자동으로 기록한 후속 확인</h4>${empty(d.followups.map(f=>`<article class="beta-card"><b>${esc(d.people[f.key]?.name)} · ${esc(f.title)}</b><p class="time-highlight">${M.dateLabel({day:f.day})} · ${f.status}</p>${f.status==='예정'?`${text('cx-follow-'+f.id,'','직접 확인한 변화와 다음 방법')}${btn('후속 확인 · 5분','beta-followup-done',attrs(f.id))}`:`<p>${esc(f.note)}</p>`}</article>`).join(''))}`);}
 function family(id){const s=get(),d=People.data(s),st=s.students.find(x=>x.id===id)||s.students[0],parents=Object.values(d.guardians).filter(g=>g.children.includes(st.personKey));page('보호자·학적 인계',`<div class="beta-row">${studentSelect('cx-student',st.id)}${btn('학생 선택','beta-family-load')}</div><div class="beta-row">${ctx.portrait(st.id,'lg')}<b class="person-highlight">${esc(st.name)}</b><span>${s.config.grade}학년 · ${st.personKey}</span></div><h4>보호자별 연락·동의 범위</h4><p class="intro">추가 보호자와 형제자매 연결은 확인 대기로 시작합니다. 가상 확인 자료에 따라 권한을 기록하며, 가족 관계만으로 연락·동의 권한을 추정하지 않습니다.</p>${parents.map(g=>{const p=g.permissions[st.personKey];return `<article class="beta-card"><div class="beta-row">${ctx.portrait(g.key,'sm')}<b>${esc(g.name)}</b></div><p>연결 학생: ${g.children.map(k=>esc(d.people[k]?.name)).join(' · ')}</p><div class="beta-checks">${[['verified','확인 자료 접수'],['messages','연락'],['consent','활동 동의'],['pickup','귀가 인계'],['records','학습 기록 안내']].map(([k,t])=>`<label><input type="checkbox" data-permission="${k}" data-guardian="${esc(g.key)}" ${p[k]?'checked':''}>${t}</label>`).join('')}</div>${btn('확인 범위 저장','beta-family-permissions',`${attrs(g.key)} data-student="${st.id}"`)}<details><summary>이 보호자와 개별 소통</summary>${text('cx-message-'+g.key,'',st.name+'에 관한 질문·안내')}${btn('확인된 권한으로 보내기','beta-family-message',`${attrs(g.key)} data-student="${st.id}"`)}${records(g.notes.filter(n=>!n.studentKey||n.studentKey===st.personKey).slice(0,4))}${field('활동 동의 주제',input('cx-consent-'+g.key,'예: 교내 독서 발표'))}<div class="buttons">${btn('동의 기록','beta-consent',`${attrs(g.key)} data-student="${st.id}" data-agree="yes"`)}${btn('미동의 기록','beta-consent',`${attrs(g.key)} data-student="${st.id}" data-agree="no"`)}</div></details></article>`;}).join('')}<div class="beta-grid">${field('추가 가상 보호자 이름',input('cx-parent-name'))}${btn('보호자 추가 · 확인 대기','beta-family-add',attrs(st.id))}${field('형제자매의 기존 보호자',select('cx-link-parent',Object.values(d.guardians).filter(g=>g.children.length&&!g.children.includes(st.personKey)).map(g=>[g.key,g.name])))}${btn('같은 보호자로 연결','beta-family-link',attrs(st.id))}</div><h4>학생 개인의 이전 이수 기록</h4>${empty(Review.priorCredits(s,st.id).map(r=>`<article class="beta-card"><b>${r.year} · ${esc(r.school)} ${r.grade}학년</b><p>${Object.entries(r.hours).map(([k,n])=>k+' '+n+'차시').join(' · ')||'개인별 확인 가능한 기록 없음'}</p><small>${r.status}</small></article>`).join(''))}<details><summary>학기 중 전입·전출</summary><p>수업 후 학적 담당자의 확인으로 진행합니다. 전출 전 개인 도서·보조도구와 지원 인계를 마칩니다. 학급 4~28명 범위이며 전입 준비물비 60,000원을 별도 추가하는 게임 규칙입니다.</p><div class="beta-grid">${field('전입 학생 이름',input('cx-arrival-name'))}${field('성별',select('cx-arrival-gender',['여','남']))}</div>${btn('전입 접수 · 적응 일정 기록','beta-transfer-in')}<div class="beta-grid">${field('전출 학교',input('cx-out-school'))}${field('인계할 내용',text('cx-out-note'))}</div>${btn(st.name+' 전출 인계 확인','beta-transfer-confirm',attrs(st.id))}<h4>남겨진 인계 기록</h4>${empty(d.transfers.slice().reverse().map(t=>`<article class="beta-card"><b>${esc(t.student.name)} · ${t.kind==='in'?'전입':'전출'}</b><small>${esc(t.date)}</small><p>${esc(t.reason)}</p>${t.kind==='out'?`<details><summary>보존된 관찰·메모</summary>${records(t.student.memories||[])}${records(t.notes||[])}</details>`:''}</article>`).join(''))}</details>`);}
 function aidPanel(st){
  const s=get(),d=People.data(s),inventory=People.aidInventory(s),available=inventory.filter(a=>a.status==='available'),labels={available:'대여 가능',loaned:'대여 중',blocked:'사용 중지 · 점검 필요',requested:'행정실 점검·수리 중',ready:'점검 완료 · 수령 확인 필요'};
  return `<h4>공용 보조도구 · 점검과 재대여</h4><p class="intro">각 도구는 학교당 1개입니다. 점검이 필요한 도구는 사용을 멈추고 다른 도구·종이 자료로 대체합니다. 담당자의 완료 안내 후 수령을 확인하면 다시 빌려줄 수 있습니다. 비용은 학교 관리 계정으로 처리하는 게임 규칙이며 학급 준비물비를 차감하지 않습니다.</p>
  <div class="beta-row">${select('cx-aid',available.map(a=>a.item))}${btn(st.name+'에게 대여 · 3분','beta-aid-lend',attrs(st.id)+(available.length?'':' disabled'))}</div>
  <div class="aid-status-list">${inventory.map(a=>{const l=a.loan,r=l?.repair;return `<article class="beta-card"><b>${esc(a.item)}</b><p role="status">${labels[a.status]}</p>${a.status==='loaned'?`<p>${esc(d.people[l.studentKey]?.name)} · ${esc(l.date)}</p>${select('cx-aid-condition-'+l.id,['양호','점검 필요'])}${btn('실물 확인 후 반납 · 3분','beta-aid-return',attrs(l.id))}`:''}
  ${a.status==='blocked'?`${text('cx-aid-note-'+l.id,'','예: 받침이 흔들려 사용 중지, 임시 독서 자료로 대체')}${btn('행정실 점검 요청 · 3분','beta-aid-repair',attrs(l.id)+' data-student="'+st.id+'"')}`:''}
  ${r&&['requested','ready'].includes(a.status)?`<p class="time-highlight">안내 예정 ${M.dateLabel({day:r.due})}</p><p>${esc(r.note)}</p>${a.status==='ready'?btn('상태 확인·수령 · 3분','beta-aid-receive',attrs(l.id)+' data-student="'+st.id+'"','primary'):btn('학교톡에서 확인','channel','data-id="admin"')}`:''}</article>`;}).join('')}</div>
  <details><summary>대여·반납·점검 이력</summary>${empty(d.loans.filter(l=>l.schoolId===(s.career?.schoolId||s.config.region)).slice().reverse().slice(0,20).map(l=>`<article class="beta-card"><b>${esc(l.item)} · ${esc(d.people[l.studentKey]?.name)}</b><small>${esc(l.date)}</small><p>${l.returned?'반납 · '+l.condition:'대여 중'}</p>${l.repair?`<p>${esc(l.repair.note)}</p><small>${esc(l.repair.requestedAt)} 접수${l.repair.closedAt?' · '+esc(l.repair.closedAt)+' 수령 확인':''}</small>`:''}</article>`).join(''))}</details>`;
 }
 function belongings(id){const s=get(),d=People.data(s),st=s.students.find(x=>x.id===id)||s.students[0],list=People.items(s,st.id);page('책상·사물함·분실물',`<div class="beta-row">${studentSelect('cx-owner',st.id)}${btn('학생 선택','beta-belongings-load')}</div><h4 class="person-highlight">${st.name}의 개인 물건</h4><div class="beta-item-grid">${list.map(item=>`<article class="beta-card"><b>${esc(item.name)}</b><small>${esc(item.state)}</small>${select('cx-place-'+item.id,Object.entries(People.tidyPlaces),item.place)}${btn('학생과 위치 확인 · 2분','beta-item-move',`${attrs(item.id)} data-student="${st.id}"`)}</article>`).join('')}</div><label class="beta-consent"><input type="checkbox" id="cx-inspect-consent"> 학생과 공개 범위·함께 정리할 내용에 동의했습니다.</label><div class="buttons">${btn('책상 속 확인 · 5분','beta-inspect',`${attrs(st.id)} data-scope="desk"`)}${btn('사물함 확인 · 5분','beta-inspect',`${attrs(st.id)} data-scope="locker"`)}</div><p class="intro">동의하지 않으면 물건 목록을 공개 검사하지 않고 자율 정리를 안내합니다. 정리 여부로 능력·가정환경을 추정하지 않습니다.</p><h4>분실물 보관함</h4>${empty(Object.values(d.belongings).flat().filter(i=>i.place==='lost').map(i=>`<article class="beta-card"><b>${esc(i.name)}</b>${studentSelect('cx-lost-owner-'+i.id)}${text('cx-clue-'+i.id,'','본인이 확인한 물건 특징·마지막 사용 장소')}${btn('주인 확인 후 반납','beta-lost-return',attrs(i.id))}</article>`).join(''))}${aidPanel(st)}<details><summary>정리 확인 이력</summary>${records(d.checks.filter(c=>c.studentKey===st.personKey).slice().reverse())}</details>`);}
 function election(){const s=get(),e=Vote.current(s);if(!e){page('전교 임원 선거',`<p class="intro">학교 전체의 가상 학생 명부를 만들고 개별 선택을 집계합니다. 후보 등록은 학생의 자발적 참여이며, 담임이 특정 후보에게 표를 주도록 지시하지 않습니다.</p><div class="beta-grid">${field('투표 가능 학년 · 게임 학교 규칙',select('cx-voter-grade',[[1,'1학년부터'],[2,'2학년부터'],[3,'3학년부터'],[4,'4학년부터']],3))}${field('후보 가능 학년',select('cx-candidate-grade',[[4,'4학년부터'],[5,'5학년부터'],[6,'6학년']],5))}</div>${btn('이번 학기 선거 공고','beta-election-start','','primary')}`);return;}
 const pool=Vote.candidates(s);page('전교 임원 선거 · '+e.term+'학기',`<div class="notice">선거인 ${e.voters.length}명 · 후보 ${e.candidates.length}명 · ${{nomination:'후보 등록',campaign:'선거운동',result:'개표 완료'}[e.stage]}<p>개별 투표 내용은 공개하지 않습니다. 동점 최다 득표자는 공동대표로 정하는 게임 학교 규칙입니다.</p></div>${e.stage==='nomination'?`<div class="beta-grid">${field('출마 희망을 확인한 학생',select('cx-candidate',pool.map(v=>[v.key,v.grade+'-'+v.room+' '+v.name+(v.classmate?' · 우리 반':'')])))}${field('공약',select('cx-pledge',Vote.PLEDGES.map(p=>[p[0],p[1]])))}</div>${btn('희망 후보 등록','beta-election-nominate')}`:''}<div class="beta-grid">${e.candidates.map(c=>`<article class="beta-card"><b>${c.grade}-${c.room} ${esc(c.name)}</b><p>${Vote.PLEDGES.find(p=>p[0]===c.pledge)[1]}</p>${e.stage==='nomination'?btn('출마 철회 반영','beta-election-remove',attrs(c.key)):''}${e.result?`<strong>${e.result.counts[c.key]}표 ${e.result.winners.includes(c.key)?'· 당선':''}</strong>`:''}</article>`).join('')}</div>${e.stage!=='result'?`<div class="buttons">${[['poster','공약 게시'],['debate','후보 질의'],['accessible','글·그림 공약 안내']].map(([k,t])=>btn(t+' · 10분','beta-election-campaign',`${attrs(k)} ${e.campaign.some(c=>c.mode===k)?'disabled':''}`)).join('')}${btn('비밀 투표·개표 · 15분','beta-election-vote','','primary')}</div>`:`<p>투표 ${e.result.cast} · 기권 ${e.result.abstain} · 미참여 ${e.result.absent} · 유효표 ${Object.values(e.result.counts).reduce((a,b)=>a+b,0)}</p>${btn('학생회 제안·실천','beta-council')}`}<details><summary>선거운동 기록</summary>${e.campaign.map(c=>`<article class="beta-card"><b>${esc(c.date)}</b>${c.speeches.map(sp=>`<p>${esc(e.candidates.find(x=>x.key===sp.key)?.name)}: ${esc(sp.text)}</p>`).join('')}</article>`).join('')}</details>`);}
 function governance(){const s=get(),d=Vote.data(s),c=d.committee.find(c=>c.year===s.academic.year),parents=Object.values(People.data(s).guardians).filter(g=>People.children(s,g).length);page('학교 위원·자율 봉사',`<h4>학교운영위원회 선출</h4><p class="intro">교원·학부모별 투표와 지역위원 추천을 분리한 가상 학교 규칙입니다. 실제 법정 정수와 선출 절차를 자동 판정하는 도구가 아닙니다.</p>${c?`<div class="notice">담임: ${W.data(s).committeeMember?'선출된 교원위원':'위원 아님 · 의견 전달 가능'}<p>교원 당선: ${c.elected.map(id=>id==='teacher'?s.config.teacherName:M.NPCS.find(n=>n.id===id)?.name).join(' · ')}</p><p>학부모 당선: ${c.parents.map(id=>esc(People.guardian(s,id)?.name)).join(' · ')}</p><p>${c.regional}</p></div>${btn('위원회 안건·의견','beta-staff')}`:`<label class="beta-consent"><input type="checkbox" id="cx-committee-stand"> 교원위원 출마에 동의합니다.</label>${btn('학교별 선출 진행 · 20분','beta-committee-election')}`}<h4>참여 희망자의 일정 배정</h4><div class="beta-grid">${field('활동',select('cx-org',['학부모회','등하굣길 안전 봉사']))}${field('희망 보호자',select('cx-volunteer',parents.map(g=>[g.key,g.name])))}${field('일자',dates('cx-vol-day'))}${field('시작',select('cx-vol-start',[[520,'08:40'],[900,'15:00'],[960,'16:00']],520))}${field('종료',select('cx-vol-end',[[540,'09:00'],[920,'15:20'],[980,'16:20']],540))}</div>${btn('희망 확인 후 배정','beta-volunteer-add')}<p>불참 가정이나 학생에게 불이익은 없습니다. 취소 시 다른 희망자 또는 학교 지원 인력을 요청합니다.</p>${empty(d.volunteers.map(v=>`<article class="beta-card"><b>${esc(v.kind)} · ${esc(v.name)}</b><p>${M.dateLabel({day:v.day})} ${M.clock(v.start)}–${M.clock(v.end)} · ${v.status}</p>${v.status==='예정'?`${select('cx-replacement-'+v.id,[['school','학교 지원 인력 요청'],...parents.filter(g=>g.key!==v.parentKey).map(g=>[g.key,g.name])])}${btn('취소·대체 희망 확인','beta-volunteer-replace',attrs(v.id))}`:`<p>${esc(v.replacement)}</p>`}${coverCard(v)}</article>`).join(''))}`);}
 function evaluation(id){const s=get(),d=Review.data(s),a=d.assessments.find(x=>x.id===id);if(a){page('평가 근거와 최종 입력 책임',`<div class="notice">${a.subject} · ${a.minutes}분 실시 · ${a.owner==='teacher'?'담임 입력':'전담교사 최종 입력'} · ${{draft:'근거 검토',review:'전담 검토 대기',final:'확정'}[a.status]}<p>${esc(a.evidence)}</p></div>${a.results.map(r=>`<article class="beta-card"><b>${esc(s.students.find(st=>st.id===r.id)?.name||'전출 학생')}</b><p>${r.participated?'실제 참여':'미참여 · 미실시 유지'}</p>${select('cx-level-'+r.id,r.participated?['잘함','보통','보완 필요','미실시']:['미실시'],r.level)}${text('cx-evidence-'+r.id,r.evidence,'이 학생에게 직접 확인한 근거')}</article>`).join('')}<div class="buttons">${btn('근거 저장','beta-assessment-save',`${attrs(a.id)} ${a.status!=='draft'?'disabled':''}`)}${btn(a.owner==='specialist'&&a.status==='draft'?'전담교사에게 인계':a.status==='review'?'전담 회신 확인·확정':'검토 후 확정','beta-assessment-final',`${attrs(a.id)} ${a.status==='final'?'disabled':''}`)}</div>`);return;}
 page('수시·보완 평가 실시',`<p class="intro">해당 과목 수업 또는 수업 후 실제 시간을 사용합니다. 학교에 없는 학생에게 결과를 부여하지 않습니다. 기존 관찰 기록 입력과 평가 실시를 구분합니다.</p><div class="beta-grid">${field('과목',select('cx-assess-subject',M.subjects(s.config.grade),M.currentSlot(s).subject))}${field('방법',select('cx-assess-kind',[['unit','단원 평가'],['dictation','받아쓰기'],['makeup','보완 평가'],['performance','수행평가']]))}${field('실제 소요 시간',select('cx-assess-time',[[5,'5분'],[10,'10분'],[15,'15분'],[20,'20분']],10))}</div>${field('확인할 활동·평가 근거',text('cx-assess-goal'))}<div class="beta-checks">${s.students.map(st=>`<label><input type="checkbox" data-assess-student="${st.id}" checked>${st.name}</label>`).join('')}</div>${btn('평가 실시 · 시간 사용','beta-assessment-run','','primary')}<h4>실시·검토 이력</h4>${empty(d.assessments.slice().reverse().map(a=>`<article class="beta-card"><b>${a.subject} · ${a.minutes}분</b><small>${a.date} · ${{draft:'초안',review:'전담 검토',final:'확정'}[a.status]}</small>${btn('근거·결과 확인','beta-evaluation',attrs(a.id))}</article>`).join(''))}`);}
 function operations(){const s=get(),d=Review.data(s),p=W.project(s);page('학교 운영 세부 기록',`<h4>업무 스킬과 준비 결과</h4><div class="beta-grid">${field('준비 영역',select('cx-prep-area',Object.entries(Review.TASKS)))}${field('만든 자료·확인한 내용',text('cx-prep-detail'))}</div>${btn('수업 후 자료 준비','beta-preparation')}<p class="intro">활성 스킬은 관련 자료 준비를 최대 8분 줄이지만 검토·정리에 에너지가 더 듭니다. 수업·상담·평가의 실제 실시 시간은 줄이지 않습니다.</p><details><summary>20개 업무 스킬의 적용 영역·장단점</summary><div class="beta-grid">${Object.entries(Review.SKILL_EFFECTS).map(([name,[area,benefit,cost]])=>`<article class="beta-card"><b>${name} · ${Review.TASKS[area]}</b><p>${benefit}</p><small>${cost}</small></article>`).join('')}</div></details>${records(d.preparation.slice(-5).reverse())}<h4>학교 휴업 결정과 실제 시수</h4>${dates('cx-closure-day')}${text('cx-closure-reason','','학교가 결정한 휴업 사유와 보완 필요 사항')}${btn('학교 결정 반영','beta-school-closure')}${empty(d.closures.map(c=>`<article class="beta-card"><b>${M.dateLabel({day:c.day})}</b><p>${esc(c.reason)} · ${c.restored?'변경 취소':'보완 확인 필요'}</p>${c.restored?'':btn('미래 휴업 변경 취소','beta-closure-undo',attrs(c.day))}</article>`).join(''))}${btn('계획·실제·부족 시수 확인','beta-school')}<h4>감사 증빙 대조</h4><div class="beta-grid">${Review.auditFindings(s).map(f=>`<article class="beta-card"><b>${f.title}</b><p>${f.ok?'현재 기록 조건 확인':'보완·확인 필요'}</p>${text('cx-audit-'+f.id,'','실제 문서와 증빙에서 확인한 내용')}${btn('증빙 기록 · 10분','beta-audit-evidence',attrs(f.id))}</article>`).join('')}</div><h4>선도사업 재지정 협의</h4><p>현재 ${p.topic} · 결과 ${p.shared?'공유 완료':'공유 전'}</p>${select('cx-renew-topic',['사회정서','AI·디지털','독서','진로','생태환경','기초학력','예술','학생자치'],p.topic)}${text('cx-renew-goal','','우리 반의 다음 지정 기간 목표와 담당 범위')}${btn('재지정 협의 · 20분','beta-project-renew')}<h4>책·사서·가상 작가와 수업 준비</h4>${select('cx-workshop-book',Library.BOOKS.map(b=>[b.id,b.title]))}${select('cx-workshop-mode',[['librarian','사서교사 읽기 지원 협의'],['author','가상 작가에게 구성 질문'],['create','학생의 새 장면 창작 보관']])}${text('cx-workshop-text','','질문 또는 학생이 새로 쓴 장면')}${btn('협의·창작 정리 · 15분','beta-book-workshop')}${empty(d.workshops.slice(-5).reverse().map(w=>`<article class="beta-card"><b>${Library.book(w.bookId).title}</b><p>${esc(w.text)}</p><blockquote>${esc(w.reply)}</blockquote></article>`).join(''))}`);}
 const pages={community,family,belongings,'election-full':election,governance,evaluation,'operations-detail':operations};
 function show(page,id){if(!pages[page])return false;pages[page](id);return true;}
 function handle(action,id,el){const s=get(),pageName=action.slice(5);if(showPageOnly(action))return show(pageName,id);let r,page,idNext;
  if(action==='beta-family-load'){family(val('cx-student'));return true;}else if(action==='beta-belongings-load'){belongings(val('cx-owner'));return true;}
  else if(action==='beta-family-add'){r=People.addGuardian(s,id,val('cx-parent-name'));page='family';idNext=id;}
  else if(action==='beta-family-link'){r=People.linkSibling(s,id,val('cx-link-parent'));page='family';idNext=id;}
  else if(action==='beta-family-permissions'){const patch=Object.fromEntries([...document.querySelectorAll('[data-permission]')].filter(e=>e.dataset.guardian===id).map(e=>[e.dataset.permission,e.checked]));r=People.permissions(s,id,el.dataset.student,patch);page='family';idNext=el.dataset.student;}
  else if(action==='beta-family-message'){r=People.familyMessage(s,id,el.dataset.student,val('cx-message-'+id));page='family';idNext=el.dataset.student;}
  else if(action==='beta-consent'){r=People.consent(s,el.dataset.student,id,val('cx-consent-'+id),el.dataset.agree==='yes');page='family';idNext=el.dataset.student;}
  else if(action==='beta-transfer-confirm'){const school=val('cx-out-school'),note=val('cx-out-note'),st=s.students.find(x=>x.id===id);open('전출 인계 확인',`<p>${esc(st.name)} 학생을 현재 명렬표에서 옮기고, 평가·메모·관계와 인계 기록은 보존합니다.</p>${field('전출 학교',`<input id="cx-out-school" value="${esc(school)}" readonly>`)}${field('인계 내용',text('cx-out-note',note))}<div class="buttons">${btn('돌아가기','beta-family',attrs(id))}${btn('확인 · 전출 처리','beta-transfer-out',attrs(id),'primary')}</div>`);return true;}
  else if(action==='beta-transfer-in'){r=People.transferIn(s,val('cx-arrival-name'),val('cx-arrival-gender'));page='family';idNext=r?.id;}
  else if(action==='beta-transfer-out'){r=People.transferOut(s,id,val('cx-out-school'),val('cx-out-note'));page='family';}
  else if(action==='beta-inspect'){r=People.inspect(s,id,el.dataset.scope,q('cx-inspect-consent')?.checked);page='belongings';idNext=id;}
  else if(action==='beta-item-move'){r=People.moveItem(s,el.dataset.student,id,val('cx-place-'+id));page='belongings';idNext=el.dataset.student;}
  else if(action==='beta-lost-return'){r=People.returnLost(s,id,val('cx-lost-owner-'+id),val('cx-clue-'+id));page='belongings';}
  else if(action==='beta-aid-lend'){r=People.lendAid(s,id,val('cx-aid'));page='belongings';idNext=id;}
  else if(action==='beta-aid-return'){r=People.returnAid(s,id,val('cx-aid-condition-'+id));page='belongings';}
  else if(action==='beta-aid-repair'){r=People.requestAidRepair(s,id,val('cx-aid-note-'+id));page='belongings';idNext=el.dataset.student;}
  else if(action==='beta-aid-receive'){r=People.confirmAidRepair(s,id);page='belongings';idNext=el.dataset.student;}
  else if(action==='beta-followup-done'){r=People.finishFollowup(s,id,val('cx-follow-'+id));page='community';}
  else if(action==='beta-election-start'){r=Vote.start(s,num('cx-voter-grade'),num('cx-candidate-grade'));page='election-full';}
  else if(action==='beta-election-nominate'){r=Vote.nominate(s,val('cx-candidate'),val('cx-pledge'));page='election-full';}
  else if(action==='beta-election-remove'){r=Vote.remove(s,id);page='election-full';}
  else if(action==='beta-election-campaign'){r=Vote.campaign(s,id);page='election-full';}
  else if(action==='beta-election-vote'){r=Vote.vote(s);page='election-full';}
  else if(action==='beta-committee-election'){r=Vote.committeeElection(s,q('cx-committee-stand')?.checked);page='governance';}
  else if(action==='beta-cover-ack'){r=Network.acknowledgeCover(s,id);page='governance';}
  else if(action==='beta-volunteer-add'){r=Vote.volunteer(s,val('cx-org'),val('cx-volunteer'),num('cx-vol-day'),num('cx-vol-start'),num('cx-vol-end'));page='governance';}
  else if(action==='beta-volunteer-replace'){r=Vote.replaceVolunteer(s,id,val('cx-replacement-'+id));page='governance';}
  else if(action==='beta-assessment-run'){r=Review.assess(s,val('cx-assess-subject'),val('cx-assess-kind'),num('cx-assess-time'),[...document.querySelectorAll('[data-assess-student]:checked')].map(e=>e.dataset.assessStudent),val('cx-assess-goal'));page='evaluation';idNext=r?.id;}
  else if(action==='beta-assessment-save'){const a=Review.data(s).assessments.find(x=>x.id===id);r=Review.editAssessment(s,id,Object.fromEntries(a.results.map(row=>[row.id,{level:val('cx-level-'+row.id),evidence:val('cx-evidence-'+row.id)}])));page='evaluation';idNext=id;}
  else if(action==='beta-assessment-final'){r=Review.finalize(s,id);page='evaluation';idNext=id;}
  else if(action==='beta-preparation'){r=Review.prepare(s,val('cx-prep-area'),val('cx-prep-detail'));page='operations-detail';}
  else if(action==='beta-school-closure'){r=Review.closure(s,num('cx-closure-day'),val('cx-closure-reason'));page='operations-detail';}
  else if(action==='beta-closure-undo'){r=Review.undoClosure(s,Number(id));page='operations-detail';}
  else if(action==='beta-audit-evidence'){r=Review.auditEvidence(s,id,val('cx-audit-'+id));page='operations-detail';}
  else if(action==='beta-project-renew'){r=Review.renew(s,val('cx-renew-topic'),val('cx-renew-goal'));page='operations-detail';}
  else if(action==='beta-book-workshop'){r=Review.workshop(s,val('cx-workshop-book'),val('cx-workshop-mode'),val('cx-workshop-text'));page='operations-detail';}
  else return false;
  if(r?.error)ctx.toast(r.error);else if(!r)ctx.toast('현재 단계에서 진행할 수 없습니다.');else{ctx.commit();show(page,idNext);}return true;
 }
 function showPageOnly(action){return action.startsWith('beta-')&&Object.hasOwn(pages,action.slice(5));}
 return {show,handle};
}
